import sys

def main():
    # Custom array-based queue implementation
    class CustomQueue:
        def __init__(self, capacity=1000):
            self.capacity = capacity
            self.queue = [0] * capacity
            self.front = 0
            self.rear = -1
            self.size = 0

        def enqueue(self, x):
            if self.size >= self.capacity:
                return  # Queue is full
            if self.rear >= self.capacity - 1:
                self.rear = 0
            else:
                self.rear += 1
            self.queue[self.rear] = x
            self.size += 1

        def dequeue(self):
            if self.size == 0:
                return -1
            result = self.queue[self.front]
            self.front += 1
            if self.front >= self.capacity:
                self.front = 0
            self.size -= 1
            return result

        def peek(self):
            if self.size == 0:
                return -1
            return self.queue[self.front]

    queue = CustomQueue()
    output = []

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        command = parts[0].lower() if parts else ""

        if command == "exit":
            break
        elif command == "enqueue":
            if len(parts) >= 2:
                try:
                    x = int(parts[1])
                    queue.enqueue(x)
                except ValueError:
                    pass
        elif command == "dequeue":
            result = queue.dequeue()
            output.append(str(result))
        elif command == "peek":
            result = queue.peek()
            output.append(str(result))

    for line in output:
        print(line)

if __name__ == "__main__":
    main()
